LEVEL = 1
CFG = {1: "call 555-0100", 2: "ssn 123-45-6789", 3: "my password is hunter2"}
text = CFG[LEVEL]
evidence = []
if "ssn" in text: evidence.append(("ssn-like", "+70", "pattern \\d{3}-\\d{2}-\\d{4}"))
if "password" in text and "is " in text: evidence.append(("credential", "+70", "'password is <value>'"))
if "555-0100" in text: evidence.append(("phone", "+40", "pattern \\d{3}-\\d{4}"))
print("text:", text)
for label, pts, why in evidence: print(" ", label, pts, "because", why)
print("labels:", [l for l, _, _ in evidence] or ["none"])

