LEVEL = 1
CFG = {1: ["public", "internal"], 2: ["internal", "secret"], 3: ["public", "secret", "top-secret"]}
RANK = {"public": 0, "internal": 1, "secret": 2, "top-secret": 3}
sources = CFG[LEVEL]
derived = max(sources, key=lambda s: RANK[s])
print("sources:", sources, "| derived sensitivity:", derived)

